      "section_39_title": "Pipeline Registration",
      "section_40_content": "Pipeline behaviors are registered by AddCoreApplication() from Mediator options. Handler scanning, request coverage validation, notification failure policy, and pipeline order are controlled from configuration.",
      "section_41_content": "<!-- Core.Application/DependencyInjection.cs --> <!-- highlight lines: 4, 5, 8, 9, 12, 15, 16 -->",
      "section_43_title": "TIP",
      "section_43_content": "Default safety validation rejects pipeline orders where Caching runs before Validation or FeatureCheck. Override Mediator__EnforceSecurityPipelineOrder only when you fully own the risk.",
      "section_44_title": "See Also",
