      "section_20_cell_5_1": "5 attempts / 15 min lockout",
      "section_20_cell_5_2": "5 attempts / 15 min lockout",
      "section_20_cell_6_0": "Session Management",
      "section_20_cell_6_1": "Revoke individual/all sessions",
      "section_20_cell_6_2": "Basic logout",
      "section_21_title": "Admin Entity (Security Features)",
      "section_22_content": "The Admin entity has several security-critical fields that control account behavior and protection.",
      "section_23_hdr_0": "Field",
      "section_23_hdr_1": "Type",
      "section_23_hdr_2": "Purpose",
      "section_23_cell_0_0": "IsSuperAdmin",
