      "section_23_cell_1_2": "Cannot be deleted, deactivated, or demoted (Guardian enforced)",
      "section_23_cell_2_0": "IsLastSuperAdminInTenant",
      "section_23_cell_2_1": "bool (cached)",
      "section_23_cell_2_2": "Safety flag  blocks deletion/deactivation if true",
      "section_23_cell_3_0": "PasswordLastChanged",
      "section_23_cell_3_1": "DateTime?",
      "section_23_cell_3_2": "Checked against TenantSettings.PasswordExpiryDays for rotation enforcement",
      "section_23_cell_4_0": "UsernameLastChanged",
      "section_23_cell_4_1": "DateTime?",
      "section_23_cell_4_2": "30-day cooldown on username changes",
      "section_23_cell_5_0": "TwoFactorEnabled",
      "section_23_cell_5_1": "bool",
      "section_23_cell_5_2": "Whether 2FA is active for this admin",
      "section_23_cell_6_0": "TwoFactorSecret",
      "section_23_cell_6_1": "string?",
      "section_23_cell_6_2": "Secret key for TOTP generation",
      "section_23_cell_7_0": "BackupCodesJson",
      "section_23_cell_7_1": "string?",
      "section_23_cell_7_2": "JSON array of hashed backup codes",
      "section_23_cell_8_0": "LastTwoFactorCodeUsed",
      "section_23_cell_8_1": "string?",
      "section_23_cell_8_2": "Anti-replay: last OTP code used",
      "section_23_cell_9_0": "LastTwoFactorCodeUsedAt",
      "section_23_cell_9_1": "DateTime?",
      "section_23_cell_9_2": "Anti-replay: timestamp of last OTP use",
      "section_23_cell_10_0": "FailedLoginAttempts",
      "section_23_cell_10_1": "int",
      "section_23_cell_10_2": "Counter for lockout threshold",
      "section_23_cell_11_0": "LockoutEnd",
      "section_23_cell_11_1": "DateTime?",
      "section_23_cell_11_2": "When lockout expires",
      "section_24_title": "Two-Factor Authentication (Deep)",
      "section_25_content": "2FA is implemented with TOTP (Time-based One-Time Password) using a per-admin TwoFactorSecret. Backup codes are hashed and stored in BackupCodesJson. Anti-replay protection ensures the same code cannot be used twice via LastTwoFactorCodeUsed and LastTwoFactorCodeUsedAt timestamps.",
      "section_26_content": "<!-- 2FA Anti-Replay Protection --> <!-- highlight lines: 2, 3, 17, 25, 26 -->",
      "section_28_title": "Tenant-Scoped Password Policy",
      "section_29_content": "Password requirements are configurable per-tenant via TenantSettings. Each tenant can set minimum length, uppercase requirements, numbers, special characters, and expiry duration. The PasswordLastChanged field on the Admin entity is checked against the tenant's PasswordExpiryDays to enforce password rotation.",
      "section_30_hdr_0": "Setting",
