      "section_35_title": "Rate Limiting",
      "section_36_content": "Authentication endpoints are protected by multiple rate limiting policies to prevent brute-force attacks and abuse.",
      "section_37_hdr_0": "Endpoint",
      "section_37_hdr_1": "Policy",
      "section_37_hdr_2": "Limit",
      "section_37_hdr_3": "Window",
      "section_37_cell_0_0": "/admin-auth/login",
      "section_37_cell_0_1": "Login",
      "section_37_cell_0_2": "5 requests",
      "section_37_cell_0_3": "15 minutes",
      "section_37_cell_1_0": "/admin-auth/refresh",
      "section_37_cell_1_1": "Refresh",
      "section_37_cell_1_2": "10 requests",
      "section_37_cell_1_3": "1 minute",
      "section_37_cell_2_0": "/admin-auth/verify-2fa",
      "section_37_cell_2_1": "2FA",
      "section_37_cell_2_2": "5 requests",
      "section_37_cell_2_3": "5 minutes",
      "section_37_cell_3_0": "/user-auth/login",
      "section_37_cell_3_1": "Login",
      "section_37_cell_3_2": "5 requests",
      "section_37_cell_3_3": "15 minutes",
      "section_37_cell_4_0": "/user-auth/register",
      "section_37_cell_4_1": "Register",
      "section_37_cell_4_2": "3 requests",
      "section_37_cell_4_3": "1 hour",
      "section_37_cell_5_0": "/user-auth/forgot-password",
      "section_37_cell_5_1": "ForgotPwd",
      "section_37_cell_5_2": "3 requests",
      "section_37_cell_5_3": "1 hour",
      "section_38_title": "WARNING",
      "section_38_content": "After 5 failed login attempts, the account is locked for 15 minutes. The lockout counter resets after a successful login. Admins can manually unlock accounts from the admin panel.",
      "section_39_title": "See Also",
      "section_40_item_0": "[Roles & Permissions](../../technical-docs/03-features)",
      "section_40_item_1": "[Audit System](../../technical-docs/03-features)",
      "section_40_item_2": "[Authentication Deep Dive](../../technical-docs/04-security)",
      "title": "Authentication"
