      "section_52_title": "TIP",
      "section_52_content": "Tenant logos are served via a static file middleware at /storage/tenants/{tenantId}/logo.{ext}. The frontend uses absolute URLs for logo display.",
      "section_53_title": "Domain Management",
      "section_54_content": "Each tenant can have multiple domains — one auto-generated subdomain created at tenant creation, plus optional custom domains added by administrators. The system supports DNS-based domain verification to prove ownership of custom domains before they become active. All domain-related configuration is fully externalized to appsettings.json, enabling seamless rebranding and multi-deployment setups.",
      "section_55_title": "Domain Types",
      "section_56_hdr_0": "Type",
      "section_56_hdr_1": "Created By",
      "section_56_hdr_2": "Example",
      "section_56_hdr_3": "Deletable",
      "section_56_hdr_4": "Auto-Verified",
      "section_56_cell_0_0": "auto",
      "section_56_cell_0_1": "System (on tenant creation)",
      "section_56_cell_0_2": "{code}.{PlatformDomain}",
      "section_56_cell_0_3": "No",
      "section_56_cell_0_4": "Yes",
      "section_56_cell_1_0": "custom",
      "section_56_cell_1_1": "Admin (via API/UI)",
      "section_56_cell_1_2": "",
      "section_56_cell_1_3": "Yes",
      "section_56_cell_1_4": "No — requires DNS verification",
      "section_57_title": "Domain Resolution Architecture",
      "section_58_content": "When a request arrives, the system resolves the tenant by looking up the hostname in the TenantDomain table. Auto-generated domains (e.g. sofa.scripe.com) are always verified and resolve immediately. Custom domains must pass DNS verification first. A fallback mechanism using the ?code= query parameter is available for development environments where DNS is not configured.",
      "section_60_title": "DNS Verification Flow",
      "section_61_content": "Custom domains require DNS verification to prove ownership. When an admin adds a custom domain, the system generates a unique verification token. The admin then configures two DNS records: a CNAME record pointing the domain to the platform's CnameTarget, and a TXT record at {VerificationPrefix}.{domain} containing the verification token. Once configured, clicking 'Verify' triggers a DNS lookup to confirm both records are present.",
      "section_63_title": "NOTE",
      "section_63_content": "DNS verification is currently a UI-driven process where the admin clicks 'Verify' to trigger the check. The backend placeholder is ready for full DNS resolution integration. Auto-generated domains skip verification entirely — they are always trusted.",
      "section_64_title": "Configurable Platform Domain",
      "section_65_content": "Every domain-related value is configurable via the Tenancy section in appsettings.json. This means you can rebrand the entire platform — changing the base domain, CNAME target, verification prefix, and token prefix — by editing a single configuration block. Zero code changes required. The backend injects TenancySettings via IOptions<T>, and the frontend receives the CNAME target and verification prefix from the GET /domains API response.",
      "section_66_content": "<!-- appsettings.json — Tenancy Section --> <!-- highlight lines: 4, 5, 6, 7 -->",
      "section_68_content": "<!-- TenancySettings.cs — Configuration POCO --> <!-- highlight lines: 5, 6, 7, 8 -->",
      "section_70_hdr_0": "Setting",
      "section_70_hdr_1": "Purpose",
      "section_70_hdr_2": "Default",
      "section_70_hdr_3": "Example Override",
      "section_70_cell_0_0": "PlatformDomain",
      "section_70_cell_0_1": "Base domain for auto-generated tenant subdomains",
      "section_70_cell_0_2": "scripe.com",
      "section_70_cell_0_3": "myapp.io",
      "section_70_cell_1_0": "CnameTarget",
      "section_70_cell_1_1": "Target shown in DNS CNAME instructions",
      "section_70_cell_1_2": "",
      "section_70_cell_1_3": "",
