      "section_71_title": "TIP",
      "section_71_content": "To deploy on a completely different domain (e.g. myplatform.io instead of scripe.com), simply update the 4 values in appsettings.json. All auto-generated subdomains, DNS instructions, and verification tokens will automatically use the new values.",
