      "section_29_title": "Frontend Module",
      "section_30_content": "The frontend module follows the standard SCRIPE module structure with domain, data, and presentation layers. The list page uses GenericCrudView for standard CRUD operations. The detail page provides 3 tabs for managing members, roles, and restrictions independently.",
      "section_31_hdr_0": "Route",
      "section_31_hdr_1": "View",
      "section_31_hdr_2": "Description",
      "section_31_cell_0_0": "/user-groups",
      "section_31_cell_0_1": "UserGroupsView",
      "section_31_cell_0_2": "CRUD list with GenericCrudView — search, paginate, create, edit, delete",
      "section_31_cell_1_0": "/user-groups/[id]",
      "section_31_cell_1_1": "UserGroupDetailView",
      "section_31_cell_1_2": "3-tab detail — Members, Roles, Restrictions with mutation support",
      "section_32_title": "NOTE",
      "section_32_content": "User Groups are tenant-scoped. SuperAdmins see all groups across tenants. Tenant admins can only manage groups within their own tenant. All mutations are audited and require the user_groups.* permission set.",
