      "section_19_title": "Guardian Protection Events",
      "section_20_content": "Guardian events are audit records created when the system BLOCKS a dangerous operation. These are the safety net that prevents catastrophic actions like deleting the last super admin in a tenant.",
      "section_21_hdr_0": "Guardian Event",
      "section_21_hdr_1": "Blocked Action",
      "section_21_hdr_2": "Why It's Blocked",
      "section_21_cell_0_0": "GuardianAdminDeleteBlocked",
      "section_21_cell_0_1": "Deleting last super admin",
      "section_21_cell_0_2": "Tenant would be orphaned with no admin access",
      "section_21_cell_1_0": "GuardianTransferBlocked",
      "section_21_cell_1_1": "Transferring last super admin out",
      "section_21_cell_1_2": "Same as above  no admin left in source tenant",
      "section_21_cell_2_0": "GuardianDemoteBlocked",
      "section_21_cell_2_1": "Removing super admin role from last holder",
      "section_21_cell_2_2": "Tenant needs at least one super admin",
      "section_21_cell_3_0": "GuardianDeactivateBlocked",
      "section_21_cell_3_1": "Deactivating last super admin",
      "section_21_cell_3_2": "All remaining admins need active super admin",
      "section_21_cell_4_0": "GuardianRoleDeleteBlocked",
      "section_21_cell_4_1": "Deleting a system/super-admin role",
      "section_21_cell_4_2": "System roles are protected from deletion",
      "section_21_cell_5_0": "GuardianRolePermissionBlocked",
      "section_21_cell_5_1": "Modifying locked role's permissions",
      "section_21_cell_5_2": "IsPermissionLocked roles cannot be changed",
      "section_21_cell_6_0": "GuardianTenantCreated",
      "section_21_cell_6_1": "N/A (informational)",
      "section_21_cell_6_2": "Logged when tenant auto-roles are created",
      "section_22_title": "WARNING",
      "section_22_content": "Guardian events are audit records created when the system BLOCKS a dangerous operation. These are the safety net that prevents catastrophic actions like deleting the last super admin in a tenant.",
      "section_23_title": "AuditService Methods",
      "section_24_content": "The IAuditService interface exposes 5 specialized logging methods, each capturing different metadata. All methods are async and fire-and-forget  they never block the main request pipeline.",
      "section_25_content": "<!-- IAuditService Interface --> <!-- highlight lines: 4, 7, 10, 14, 18 -->",
      "section_27_title": "Real-Time Broadcasting",
      "section_28_content": "Every audit event is broadcast in real-time via SignalR. Connected clients receive events scoped to their tenant, enabling live audit dashboards and instant security alerts. Events are sent to both the tenant group and a global group (for super admins).",
      "section_29_content": "<!-- AuditHub  SignalR Broadcasting --> <!-- highlight lines: 3, 15 -->",
      "section_31_title": "Audit Export",
      "section_32_content": "The AuditExportService supports CSV and PDF export of filtered audit logs. Exports respect tenant scoping  admins can only export logs from their own tenant and child tenants.",
      "section_33_title": "Audit API Endpoints",
      "section_34_hdr_0": "Method",
      "section_34_hdr_1": "Endpoint",
      "section_34_hdr_2": "Description",
      "section_34_hdr_3": "Auth",
      "section_34_hdr_4": "Permission",
      "section_34_cell_0_0": "`GET`",
