      "section_14_cell_0_1": "Create + persist + push via SignalR",
      "section_14_cell_1_0": "GetUnreadCountAsync(userId)",
      "section_14_cell_1_1": "Count unread notifications",
      "section_14_cell_2_0": "MarkAsReadAsync(notificationId)",
      "section_14_cell_2_1": "Mark single notification as read",
      "section_14_cell_3_0": "MarkAllAsReadAsync(userId)",
      "section_14_cell_3_1": "Mark all notifications as read",
      "section_14_cell_4_0": "GetPagedAsync(userId, page, size)",
      "section_14_cell_4_1": "Paginated notification list",
