      "section_28_cell_7_2": "Role permissions modified",
      "section_28_cell_8_0": "audit.security_event",
      "section_28_cell_8_1": "EventType + metadata",
      "section_28_cell_8_2": "Guardian or security event",
      "section_29_title": "Subscription Management",
