      "section_13_cell_2_2": "[Transfer 'protected' flag]",
      "section_13_cell_2_3": "Super admin",
      "section_13_cell_2_4": "--",
      "section_14_title": "Protected Admin Rules",
      "section_15_content": "Each tenant has exactly one protected admin  the super admin who created the tenant. The protected flag prevents accidental deletion or deactivation of the tenant's primary administrator.",
      "section_16_item_0": "Each tenant has exactly one protected admin (the super admin who created the tenant)",
      "section_16_item_1": "Protected flag can be transferred to another admin via TransferProtection",
      "section_16_item_2": "Protected admins cannot be deleted, deactivated, or have roles removed",
      "section_18_title": "Nuke & Pave Pattern",
      "section_19_content": "<!-- AdminsController.cs -->",
      "section_21_title": "TIP",
      "section_21_content": "Use Nuke & Pave (PUT /admins/{id}/roles/sync) instead of individual add/remove when assigning roles from a UI checklist. It eliminates race conditions and ensures the database always matches the UI state exactly.",
      "section_22_title": "See Also",
