      "section_9_title": "NOTE",
      "section_9_content": "Split layouts render the LoginBranding component with independent overlay/blur controls on the branding panel. Full-page layouts apply background and overlay to the entire wrapper. Centered and Special layouts each have their own rendering strategies. Switching layouts preserves all configuration — only the rendering structure changes.",
      "section_10_title": "Design Tokens Pipeline",
      "section_11_content": "The customization system is built on a comprehensive design token pipeline. Tenant settings stored as JSON are transformed into semantic design tokens, which are then emitted as CSS custom properties and injected into the live DOM. This architecture ensures consistent, type-safe styling across all 22 layouts, including 23+ accessibility-specific CSS rules.",
