      "section_13_cell_10_2": "none",
      "section_13_cell_10_3": "Background upload",
      "section_14_title": "Background & Overlay Controls",
      "section_15_content": "Background and overlay controls adapt based on the selected layout type. Full-page layouts apply backgrounds and overlays to the wrapper container, while Split layouts scope backgrounds to the branding panel with independent form-section overlays. Overlay controls include color, opacity (0–100%), and blur (0–20px).",
      "section_16_hdr_0": "Layout Type",
      "section_16_hdr_1": "Background Image",
      "section_16_hdr_2": "Overlay Support",
      "section_16_hdr_3": "Branding Panel",
