      "section_16_cell_1_1": "On branding panel only",
      "section_16_cell_1_2": "✅ On form + branding sections",
      "section_16_cell_1_3": "✅ Independent controls",
      "section_17_title": "WARNING",
      "section_17_content": "For split layouts, the overlay is scoped to the form section and branding panel independently. CSS variables with a value of 0 (e.g., opacity) are correctly emitted — the system uses != null checks rather than truthiness checks to prevent dropping valid zero values.",
      "section_18_title": "Light/Dark Theme Architecture",
      "section_19_content": "The Login Customizer supports independent light and dark mode configurations. When dark mode is enabled, a separate set of CSS variables is emitted for the dark panel (--login-dark-*), controlling form background, text color, input styling, and overlay. The dark mode toggle in the Appearance panel allows complete control over the dark theme without affecting the light configuration.",
