      "section_24_title": "Draft / Publish / Rollback",
      "section_25_content": "The studio implements a safe Draft → Preview → Publish workflow using optimistic concurrency control. All changes are saved as drafts (DraftBrandingJson) until the admin explicitly publishes. Publishing increments the SettingsVersion counter — concurrent publishes from other admins are rejected with a 409 Conflict. Any previously published version can be rolled back from the audit log snapshots.",
      "section_27_title": "NOTE",
      "section_27_content": "Optimistic concurrency prevents data loss from concurrent editing. If another admin publishes while you're editing, your publish will be rejected (409), and you'll need to refresh and merge your changes.",
      "section_28_title": "Safe Mode",
      "section_29_content": "Safe Mode is an emergency fallback that bypasses all tenant branding and restores platform defaults for the login page. When IsSafeMode is set to true on TenantSettings, the login page renders with the default SCRIPE theme regardless of any customization. This ensures a guaranteed working login experience even if branding configuration becomes corrupted.",
      "section_30_title": "Access Control",
      "section_31_content": "Login customization follows SCRIPE's role-based access control model. Opening the Customizer Studio requires the branding.manage permission. System Admins and Tenant Admins with the appropriate permission can edit and publish. Regular admins can only toggle personal preferences like dark/light mode. Safe mode activation is restricted to System Admins only.",
      "section_32_hdr_0": "Action",
      "section_32_hdr_1": "System Admin",
      "section_32_hdr_2": "Tenant Admin (perm)",
      "section_32_hdr_3": "Regular Admin",
