      "section_14_cell_3_0": "ThumbnailUrl",
      "section_14_cell_3_1": "string?",
      "section_14_cell_3_2": "Preview image URL for gallery cards",
      "section_14_cell_4_0": "PreviewUrl",
      "section_14_cell_4_1": "string?",
      "section_14_cell_4_2": "Full-size preview for the detail modal",
      "section_14_cell_5_0": "ThemeDataJson",
      "section_14_cell_5_1": "JSON",
      "section_14_cell_5_2": "Complete design specification (50+ tokens)",
      "section_14_cell_6_0": "Tier",
      "section_14_cell_6_1": "enum",
      "section_14_cell_6_2": "Free, Starter, Professional, Enterprise, StandaloneAddon",
