      "section_14_cell_9_0": "Tags",
      "section_14_cell_9_1": "string?",
      "section_14_cell_9_2": "Comma-separated search tags",
      "section_14_cell_10_0": "Version",
      "section_14_cell_10_1": "string",
      "section_14_cell_10_2": "Semantic version (e.g., '1.0.0')",
      "section_14_cell_11_0": "Author",
      "section_14_cell_11_1": "string",
      "section_14_cell_11_2": "Creator identifier",
      "section_14_cell_12_0": "LikesCount",
      "section_14_cell_12_1": "int",
      "section_14_cell_12_2": "Engagement: how many tenants favorited",
      "section_14_cell_13_0": "AppliedCount",
      "section_14_cell_13_1": "int",
      "section_14_cell_13_2": "Usage: how many tenants applied",
      "section_15_title": "ThemeDataJson Schema (50+ Design Tokens)",
      "section_16_content": "The ThemeDataJson column stores a comprehensive JSON object containing every visual parameter needed to fully render a branded login page. The schema is versioned and contains 7 major sections: layout, colors, dark mode colors, typography, spacing, overlay, and branding panel. Each token maps directly to a CSS custom property via the useLoginBrandingTokens pipeline.",
      "section_17_title": "Layout Configuration",
      "section_18_content": "Controls the page structure: selectedLayout (one of 22 layout identifiers), loginPosition (left/center/right), formWidth, formMaxWidth, containerPadding, and formAlignment. Layout selection determines which rendering strategy the LoginPage component uses.",
      "section_19_title": "Color System (16 Tokens)",
      "section_20_content": "The colors section defines the complete light-mode palette: primaryColor (brand accent), secondaryColor (complementary), backgroundColor (page background), formBackground (form card), textColor (primary text), secondaryTextColor (muted text), inputBackground (form input fields), inputBorderColor, inputTextColor, buttonColor (primary CTA), buttonTextColor, buttonHoverColor, linkColor, linkHoverColor, borderColor (general borders), and accentColor (highlights/badges).",
      "section_21_title": "Dark Mode Color System (10 Tokens)",
      "section_22_content": "Independent dark-mode palette: darkEnabled (boolean toggle), darkFormBackground, darkTextColor, darkInputBackground, darkInputBorderColor, darkInputTextColor, darkButtonColor, darkButtonTextColor, darkSecondaryTextColor, and darkBorderColor. These tokens are emitted as --login-dark-* CSS variables and activated via the [data-theme='dark'] selector.",
      "section_23_title": "Typography Configuration (8 Tokens)",
      "section_24_content": "Controls all text rendering: fontFamily (Google Fonts name, e.g., 'Playfair Display'), headingFontFamily (optional separate heading font), fontSize (base size in px), headingSize, labelSize, inputFontSize, fontWeight (normal/medium/semibold/bold), and letterSpacing. Fonts are loaded dynamically via the Google Fonts CDN.",
      "section_25_title": "Spacing & Dimensions (6 Tokens)",
      "section_26_content": "Controls layout geometry: borderRadius (global border-radius in px), inputBorderRadius, buttonBorderRadius, inputHeight (in px), buttonHeight, and gap (spacing between form elements). These values are emitted as CSS custom properties and applied uniformly across all 22 layouts.",
      "section_27_title": "Overlay & Effects (8 Tokens)",
      "section_28_content": "Controls visual effects layered on backgrounds: overlayColor (RGBA), overlayOpacity (0–100%), overlayBlur (0–20px in Gaussian blur), backgroundType ('color', 'gradient', 'image'), backgroundValue (CSS gradient string or image URL), backgroundSize, backgroundPosition, and backgroundRepeat. Overlay settings can be scoped to the form section or branding panel independently.",
      "section_29_title": "Branding Panel Configuration (12 Tokens)",
      "section_30_content": "Controls the branding side of split layouts: panelLogo (URL), panelHeadline (heading text), panelSubtitle (subheading text), panelHeadlineColor, panelSubtitleColor, panelBackgroundType, panelBackgroundValue, panelOverlayColor, panelOverlayOpacity, panelOverlayBlur, panelLogoSize (small/medium/large), and panelAlignment (left/center/right). These tokens are only rendered in T1 Split layouts.",
