      "section_52_title": "Frontend Component Inventory",
      "section_53_content": "The Theme Marketplace frontend consists of 8 purpose-built components spanning 3 pages and 1 modal. Each component follows SCRIPE's presentation-layer patterns using domain entities (never DTOs) and consuming data exclusively through the DI container.",
      "section_54_hdr_0": "Component",
      "section_54_hdr_1": "Size",
      "section_54_hdr_2": "Purpose",
      "section_54_cell_0_0": "ThemeGalleryView",
      "section_54_cell_0_1": "26KB",
      "section_54_cell_0_2": "Full-page marketplace — hero, filters, grid/list, pagination",
