      "section_54_cell_2_0": "ThemeDetailModal",
      "section_54_cell_2_1": "28KB",
      "section_54_cell_2_2": "Detail preview — feature matrix, apply, like/favorite",
      "section_54_cell_3_0": "ThemeCard",
      "section_54_cell_3_1": "~5KB",
      "section_54_cell_3_2": "Gallery card — palette strip, font preview, engagement",
      "section_54_cell_4_0": "ThemeMarketplacePanel",
      "section_54_cell_4_1": "~4KB",
      "section_54_cell_4_2": "Inline studio panel with quick-apply",
      "section_55_title": "Theme Application Flow",
      "section_56_content": "Applying a marketplace theme follows a 5-step pipeline: 1. User clicks Apply on a theme. 2. Frontend reads the theme's ThemeDataJson. 3. previewTheme() in useStudioViewModel merges the design tokens (including per-page overrides) into the current StudioDraft. 4. The merged draft is saved to the tenant's DraftBrandingJson via PUT /tenants/{id}/settings. 5. Admin publishes the draft to make it live.",
      "section_57_title": "Copy-on-Apply Snapshot Semantics",
      "section_58_content": "When a theme is applied, the ThemeDataJson is COPIED into the tenant's DraftBrandingJson — not linked. This means the tenant's branding is permanently isolated from future marketplace updates. If the theme is updated in v2.0, existing tenants who applied v1.0 retain their v1.0 snapshot. This prevents unexpected visual changes to production login pages.",
      "section_59_title": "WARNING",
      "section_59_content": "Copy-on-apply is a deliberate architectural decision. It trades storage efficiency for deployment safety — a critical requirement for enterprise tenants who negotiate specific branding contracts.",
      "section_60_title": "Preview Before Apply",
      "section_61_content": "The previewTheme() function in useStudioViewModel.ts performs a non-destructive preview by temporarily injecting theme tokens into the draft state. The preview is displayed in the sandboxed iframe via postMessage CSS variable injection. The draft is NOT saved until the user explicitly confirms the application. Canceling the preview restores the previous draft state.",
      "section_63_title": "Backend Seeding Architecture",
      "section_64_content": "All 40 themes are seeded at application startup by LoginThemeSeeder.cs. The seeder uses an upsert-safe strategy: it checks for existing themes by Name and only inserts new ones — existing themes are never overwritten. This ensures idempotent deployment across environments.",
      "section_65_title": "Build() Helper Architecture",
      "section_66_content": "The seeder uses a fluent Build() helper with ThemeMeta and ThemeDesign records for clean theme definition. ThemeMeta contains name, category, tier, description, author, version, and tags. ThemeDesign contains all 50+ design tokens plus per-page overrides (PageOverrideDesign records for ForgotPassword and ResetPassword). The BuildFullThemeJson() method serializes the ThemeDesign record into the JSON format expected by the frontend.",
      "section_67_content": "<!-- LoginThemeSeeder.cs — Build() Helper -->",
      "section_69_title": "Upsert-Safe Strategy",
      "section_70_content": "The seeder queries all existing theme names before processing. For each of the 40 themes, it checks the existing set — if the name exists, the theme is skipped. New themes are added to the DbContext in a single batch and saved with one SaveChangesAsync call. This makes the seeder safe to run repeatedly without duplicating themes or losing manual edits.",
      "section_71_title": "Marketplace Governance",
      "section_72_content": "Theme access is controlled by a combination of edition-based tier enforcement and permission-based administrative access. The marketplace respects SCRIPE's multi-tenancy model — themes are globally visible but apply operations are scoped to the current tenant.",
      "section_73_hdr_0": "Action",
      "section_73_hdr_1": "Required Permission",
      "section_73_hdr_2": "Enforcement",
      "section_73_cell_0_0": "Browse marketplace",
