      "section_73_cell_3_0": "Like/favorite",
      "section_73_cell_3_1": "branding.view",
      "section_73_cell_3_2": "Per-admin tracking",
      "section_74_title": "Theme API Endpoints",
      "section_75_content": "The theme marketplace exposes endpoints through the existing TenantSettings and Themes controllers. Theme data is served as part of the branding configuration pipeline.",
