      "section_22_cell_2_3": "Always",
      "section_22_cell_3_0": "Component Styles",
      "section_22_cell_3_1": "16",
      "section_22_cell_3_2": "buttonStyle, inputStyle, tableStyle",
      "section_22_cell_3_3": "ComponentStyles.Enabled",
