      "section_46_item_1": "[Audit System](../../technical-docs/03-features)",
      "section_46_item_2": "[Enterprise Audit Trail](../../technical-docs/07-infrastructure)",
      "title": "Dashboard Hub (Hub-and-Spoke)"
