      "section_16_title": "External Authentication",
      "section_17_content": "SCRIPE supports OAuth authentication via Google, Facebook, Apple, or Microsoft. The client obtains a provider token and sends it to the external-login endpoint. SCRIPE validates the token, creates or links the account, and returns JWT tokens.",
