      "section_15_cell_0_2": "Activate a deactivated admin account.",
      "section_15_cell_0_3": "admins.update",
      "section_15_cell_0_4": "--",
      "section_15_cell_1_0": "`POST`",
      "section_15_cell_1_1": "`/api/v1/admins/{id}/deactivate`",
