      "section_15_cell_4_0": "`POST`",
      "section_15_cell_4_1": "`/api/v1/admins/{id}/unlock`",
      "section_15_cell_4_2": "Unlock a locked-out account (reset failed login attempts).",
      "section_15_cell_4_3": "admins.update",
      "section_15_cell_4_4": "--",
