      "section_15_cell_5_3": "admins.update",
      "section_15_cell_5_4": "--",
      "section_16_title": "Bulk Operations",
      "section_17_content": "Bulk operations accept either an array of specific IDs or a filter object that matches all records meeting criteria. The bulk-delete-all variant uses the current filter context to select records, with an optional excludeIds array to protect specific accounts.",
      "section_18_hdr_0": "Method",
      "section_18_hdr_1": "Endpoint",
      "section_18_hdr_2": "Description",
      "section_18_hdr_3": "Auth",
      "section_18_hdr_4": "Permission",
      "section_18_cell_0_0": "`POST`",
      "section_18_cell_0_1": "`/api/v1/admins/bulk-activate`",
      "section_18_cell_0_2": "Activate multiple admin accounts by ID list.",
      "section_18_cell_0_3": "admins.update",
      "section_18_cell_0_4": "--",
      "section_18_cell_1_0": "`POST`",
      "section_18_cell_1_1": "`/api/v1/admins/bulk-deactivate`",
      "section_18_cell_1_2": "Deactivate multiple admin accounts by ID list.",
