      "section_18_cell_3_3": "admins.delete",
      "section_18_cell_3_4": "--",
      "section_19_title": "Bulk by IDs",
      "section_20_content": "<!-- POST /admins/bulk-delete — By ID Selection -->",
      "section_22_title": "Bulk All (Filtered)",
