      "section_25_title": "Impersonation",
      "section_26_hdr_0": "Method",
      "section_26_hdr_1": "Endpoint",
      "section_26_hdr_2": "Description",
      "section_26_hdr_3": "Auth",
      "section_26_hdr_4": "Permission",
      "section_26_cell_0_0": "`POST`",
      "section_26_cell_0_1": "`/api/v1/admins/{id}/impersonate`",
      "section_26_cell_0_2": "Start impersonating another admin. Receive their JWT with your audit trail attached.",
      "section_26_cell_0_3": "SuperAdmin only",
      "section_26_cell_0_4": "--",
      "section_26_cell_1_0": "`POST`",
      "section_26_cell_1_1": "`/api/v1/admins/stop-impersonation`",
      "section_26_cell_1_2": "Stop impersonation and return to your original admin session.",
      "section_26_cell_1_3": "Impersonating admin",
      "section_26_cell_1_4": "--",
      "section_26_cell_2_0": "`POST`",
      "section_26_cell_2_1": "`/api/v1/admins/{id}/transfer`",
      "section_26_cell_2_2": "Transfer SuperAdmin role to another admin. You lose SuperAdmin privileges.",
      "section_26_cell_2_3": "SuperAdmin only",
      "section_26_cell_2_4": "--",
      "section_26_cell_3_0": "`POST`",
      "section_26_cell_3_1": "`/api/v1/admins/{id}/protect`",
      "section_26_cell_3_2": "Toggle protection flag on an admin account (protected accounts cannot be deleted).",
      "section_26_cell_3_3": "SuperAdmin only",
      "section_26_cell_3_4": "--",
      "section_27_title": "WARNING",
      "section_27_content": "Impersonation is a powerful feature restricted to SuperAdmins. All actions performed during impersonation are logged with both the impersonator's and the target's identity. The impersonation session is time-limited and automatically ends after 1 hour.",
      "section_28_title": "Query Parameters",
