      "section_11_cell_5_0": "user.verified",
      "section_11_cell_5_1": "Email/phone verified",
      "section_11_cell_5_2": "userId, verificationType",
      "section_11_cell_6_0": "tenant.created",
      "section_11_cell_6_1": "New tenant created",
