      "section_11_cell_10_2": "userId, lockoutEnd",
      "section_12_title": "Email System",
      "section_13_content": "The email system supports individual and bulk email sending with template variable interpolation. Emails are queued via background services and processed asynchronously. The system supports scheduling, cancellation, and resending of failed emails.",
      "section_14_hdr_0": "Method",
      "section_14_hdr_1": "Endpoint",
      "section_14_hdr_2": "Description",
      "section_14_hdr_3": "Auth",
      "section_14_hdr_4": "Permission",
      "section_14_cell_0_0": "`GET`",
      "section_14_cell_0_1": "`/api/v1/emails`",
      "section_14_cell_0_2": "List sent/queued/failed emails with pagination and status filters.",
      "section_14_cell_0_3": "emails.view",
      "section_14_cell_0_4": "--",
