      "section_14_cell_1_1": "`/api/v1/emails/send`",
      "section_14_cell_1_2": "Send a single email using a template with variable substitution.",
      "section_14_cell_1_3": "emails.send",
      "section_14_cell_1_4": "--",
      "section_14_cell_2_0": "`POST`",
      "section_14_cell_2_1": "`/api/v1/emails/send-bulk`",
      "section_14_cell_2_2": "Send bulk emails to multiple recipients or a filtered group.",
      "section_14_cell_2_3": "emails.send",
