      "section_14_cell_5_0": "`GET`",
      "section_14_cell_5_1": "`/api/v1/emails/stats`",
      "section_14_cell_5_2": "Get email statistics (sent, failed, queued, bounce rate).",
      "section_14_cell_5_3": "emails.view",
      "section_14_cell_5_4": "--",
