      "section_14_cell_6_2": "Search for valid email recipients (admins/users) by name or email.",
      "section_14_cell_6_3": "emails.send",
      "section_14_cell_6_4": "--",
      "section_15_title": "Send Email",
      "section_16_content": "<!-- POST /emails/send — Request -->",
      "section_18_title": "Send Bulk",
      "section_19_content": "<!-- POST /emails/send-bulk — Request -->",
      "section_21_title": "Message Templates",
      "section_22_content": "Message templates use the Scriban engine (Liquid-compatible) for variable interpolation. Templates support HTML and plain-text bodies, with preview and render endpoints for testing before sending.",
      "section_23_hdr_0": "Method",
      "section_23_hdr_1": "Endpoint",
      "section_23_hdr_2": "Description",
      "section_23_hdr_3": "Auth",
      "section_23_hdr_4": "Permission",
      "section_23_cell_0_0": "`GET`",
      "section_23_cell_0_1": "`/api/v1/message-templates`",
