      "section_4_cell_6_1": "Edition-based feature gating & plan management",
      "section_4_cell_6_2": "Features, editions, subscriptions, overrides, quota enforcement, versioned rollouts, reseller scoping",
      "section_5_title": "Communication & Webhooks",
      "section_6_hdr_0": "Module",
      "section_6_hdr_1": "Description",
      "section_6_hdr_2": "Key Capabilities",
      "section_6_cell_0_0": "Notifications",
      "section_6_cell_0_1": "Real-time push notifications",
      "section_6_cell_0_2": "SignalR WebSockets, auto-join by tenant, mark read/unread, bell UI",
      "section_6_cell_1_0": "Email System",
      "section_6_cell_1_1": "Transactional email pipeline",
