      "section_0_content": "Three deployment topologies from a single codebase: Monolith, Distributed Gateway, and Independent Microservices.",
      "section_1_content": "SCRIPE was engineered to solve the hardest problem in distributed systems: deciding when to split. Our architecture supports three deployment modes out-of-the-box from the exact same codebase, allowing you to start simple and scale infinitely without the cost of a massive refactor.",
