      "section_4_cell_2_0": "Auth page consistency (login/forgot/reset)",
      "section_4_cell_2_1": "Manual CSS duplication across 3 pages",
      "section_4_cell_2_2": "Per-page branding built into every theme — instant.",
      "section_4_cell_3_0": "Brand safety for production",
      "section_4_cell_3_1": "Risky direct CSS edits to live pages",
      "section_4_cell_3_2": "Draft → Preview → Publish with instant rollback.",
      "section_4_cell_4_0": "Upsell opportunities",
      "section_4_cell_4_1": "No natural upgrade triggers",
      "section_4_cell_4_2": "Premium themes visible-but-locked for lower tiers — natural upgrade.",
      "section_4_cell_5_0": "Dark mode support",
      "section_4_cell_5_1": "Additional development sprint ($5K–$15K)",
      "section_4_cell_5_2": "Every theme includes independent dark mode tokens.",
      "section_5_title": "40 Premium Branding Packages",
      "section_6_content": "Each theme is a comprehensive visual identity — not just a color swap. Every package includes 50+ coordinated design tokens: a full light-mode color palette (16 tokens), independent dark-mode palette (10 tokens), typography system (8 tokens including Google Font pairing), spacing and dimension settings (6 tokens), overlay and background effects (8 tokens), branding panel configuration (12 tokens), and per-page overrides for Login, Forgot Password, and Reset Password. No two themes share the same font pairing or color palette.",
      "section_7_title": "7 Market-Targeted Categories",
      "section_8_content": "Themes are organized into categories that map to specific market segments, enabling tenant administrators to find their ideal visual identity quickly.",
