      "section_10_title": "5-Tier Edition-Aligned Pricing",
      "section_11_content": "Theme access is automatically gated to the tenant's subscribed edition. Lower-tier tenants see premium themes with an 'Upgrade Required' badge — creating a frictionless upsell path that drives subscription upgrades. No manual enforcement needed.",
      "section_12_hdr_0": "Tier",
