      "section_13_title": "Enterprise-Grade Marketplace Experience",
      "section_14_content": "The Theme Marketplace is a full-page gallery experience integrated directly into the admin panel. Tenant administrators can browse themes with category filters, tier tabs, and search — preview any theme in real-time on their actual login page — and apply with a single click. The entire flow from browsing to deployment takes under 60 seconds.",
      "section_15_hdr_0": "Feature",
      "section_15_hdr_1": "Description",
      "section_15_cell_0_0": "Rich Browsing",
      "section_15_cell_0_1": "Animated hero, category filters, tier tabs, search, grid/list toggle, infinite scroll",
      "section_15_cell_1_0": "Real-Time Preview",
      "section_15_cell_1_1": "Click any theme → fully rendered preview on your actual login page",
      "section_15_cell_2_0": "One-Click Deploy",
      "section_15_cell_2_1": "Apply copies 50+ tokens into draft → review → publish when ready",
      "section_15_cell_3_0": "Engagement Analytics",
      "section_15_cell_3_1": "LikesCount and AppliedCount reveal which designs resonate",
      "section_16_title": "Per-Page Branding — Complete Auth Experience",
      "section_17_content": "Unlike basic theme systems that apply one look across all pages, every SCRIPE theme can define independent visual treatments for Login, Forgot Password, and Reset Password. This lets tenants present context-appropriate messaging: a strong brand statement on login, a reassuring message on forgot-password, and a clear action prompt on reset-password — all within a cohesive visual identity.",
      "section_18_title": "Copy-on-Apply — Enterprise-Grade Safety",
      "section_19_content": "When a theme is applied, it's COPIED — not linked. Your tenant's branding is permanently isolated from future marketplace updates. If the marketplace theme is updated to v2.0, tenants who applied v1.0 retain their exact snapshot. This architectural decision trades storage efficiency for deployment safety — a critical requirement for enterprises whose branding is contractually defined.",
      "section_20_title": "Provable ROI Metrics",
