      "section_9_hdr_1": "Controls Implemented",
      "section_9_hdr_2": "Evidence Available",
      "section_9_cell_0_0": "Access Control",
      "section_9_cell_0_1": "RBAC, field-level restrictions, MFA",
      "section_9_cell_0_2": "User access logs, permission audit",
      "section_9_cell_1_0": "Data Protection",
