      "section_5_title": "Frictionless Provider Switching",
      "section_6_content": "Switch database providers via a single line in appsettings.json. Toggle between Single-database mode (all modules share one DB) and Multi-database mode (each module gets its own DB) with the Database.Mode setting. Move from a single PostgreSQL instance in development to isolated Oracle RAC databases per module in production—seamlessly.",
