      "section_3_cell_7_2": "Email, IP, attempt count",
      "section_4_title": "HMAC Cryptographic Signatures",
      "section_5_content": "Every outbound payload is securely signed using an HMAC-SHA256 signature generated from the tenant's secret key. Third-party integrations can definitively verify that the webhook originated from your SCRIPE servers and the payload was not intercepted or mutated globally.",
      "section_6_content": "<!-- Webhook Delivery Security -->",
      "section_8_title": "Exponential Persistent Backoff",
      "section_9_content": "If a subscriber's server goes offline, SCRIPE does not discard the payload. Utilizing an intelligent, exponentially backed-off persistent outbox pattern, it mathematically retries the request (e.g., 5 seconds, 1 minute, 1 hour, 1 day) until receipt is confirmed via an HTTP 2xx status.",
