    "emailIntegration": {
      "section_0_content": "Asynchronous, queue-based transactional email delivery with rich customizable Scriban templating.",
      "section_1_content": "Transactional communications must never block an API request. SCRIPE includes an outbox-pattern, queue-based dispatch system leveraging background worker processes to guarantee hyper-fast, reliable email delivery via standard SMTP or direct REST APIs like SendGrid and Mailgun.",
      "section_2_title": "The Transactional Pipeline",
      "section_4_title": "Agnostic Transport Providers",
      "section_5_hdr_0": "Provider",
      "section_5_hdr_1": "Configuration",
      "section_5_hdr_2": "Use Case",
      "section_5_cell_0_0": "SMTP",
      "section_5_cell_0_1": "Host, port, credentials",
      "section_5_cell_0_2": "Self-hosted, on-premise",
      "section_5_cell_1_0": "SendGrid",
      "section_5_cell_1_1": "API key",
      "section_5_cell_1_2": "Cloud, high-volume delivery",
      "section_5_cell_2_0": "Mailgun",
      "section_5_cell_2_1": "API key + domain",
      "section_5_cell_2_2": "Developer-friendly API",
      "section_5_cell_3_0": "Amazon SES",
      "section_5_cell_3_1": "Access key + region",
      "section_5_cell_3_2": "AWS infrastructure",
      "section_5_cell_4_0": "Custom",
      "section_5_cell_4_1": "Implement IEmailSender",
      "section_5_cell_4_2": "Any provider via adapter",
      "section_6_title": "Intelligent Scriban Templating",
      "section_7_content": "Write logic immediately inside your email layouts. Using the blazing-fast Scriban templating language, you can execute conditional blocks, iterate over items, and perfectly format dates without leaking business logic into your application layer.",
      "section_8_hdr_0": "Feature",
      "section_8_hdr_1": "Description",
      "section_8_cell_0_0": "Scriban engine",
      "section_8_cell_0_1": "Full Liquid-compatible templating with loops, conditions, filters",
      "section_8_cell_1_0": "Bilingual",
      "section_8_cell_1_1": "Arabic and English templates with automatic language detection",
      "section_8_cell_2_0": "Placeholder validation",
      "section_8_cell_2_1": "Schema-validated variables prevent runtime template errors",
      "section_8_cell_3_0": "Live preview",
      "section_8_cell_3_1": "WYSIWYG editor with real-time rendering in the admin panel",
      "section_8_cell_4_0": "Version history",
      "section_8_cell_4_1": "Track template changes with rollback capability",
      "section_9_title": "Enterprise Delivery Features",
      "section_10_title": "zap Background Dispatches",
      "section_11_content": "APIs respond strictly under 50ms, while heavy string manipulations and external network calls are delegated to persistent background services.",
      "section_12_title": "globe Bilingual Template Routing",
      "section_13_content": "Automatically detect tenant locales and dispatch deeply personalized HTML emails in Arabic (RTL) or English (LTR) from strictly categorized templates.",
      "section_14_title": "shield Exponential Backoff",
      "section_15_content": "Gracefully handle temporary network partitions or rate-limits from external providers with built-in, configurable resilient retry policies.",
      "section_16_title": "bar-chart Audit & Delivery Tracking",
      "section_17_content": "Record the dispatch ID, exact timestamp, and provider response for every single email sent, creating an undeniable audit trail.",
      "section_18_title": "Dynamic SMTP Configurations",
      "section_19_content": "<!-- Email Configuration -->",
      "section_21_title": "See Also",
      "section_22_item_0": "[High-Volume Webhook Dispatch](../../commercial-docs/16-integration)",
      "section_22_item_1": "[Dynamic Message Templating](../../commercial-docs/12-enterprise)",
      "title": "Resilient Email Infrastructure"
    },
