      "section_18_cell_4_4": "`Editions.Update`",
      "section_18_cell_5_0": "`POST`",
      "section_18_cell_5_1": "`/api/editions/{id}/versions`",
      "section_18_cell_5_2": "[Create edition version]",
      "section_18_cell_5_3": "Required",
      "section_18_cell_5_4": "`Editions.Update`",
      "section_18_cell_6_0": "`POST`",
      "section_18_cell_6_1": "`/api/editions/{id}/versions/{vId}/apply`",
      "section_18_cell_6_2": "[Apply version (rollout)]",
      "section_18_cell_6_3": "Required",
      "section_18_cell_6_4": "`Editions.Update`",
      "section_19_title": "TIP",
      "section_19_content": "Editions are never deleted from the database — they are soft-deleted to preserve subscription history and audit trails. Active subscriptions prevent edition deletion entirely.",
