      "section_30_cell_6_2": "[Reactivate subscription]",
      "section_30_cell_6_3": "Required",
      "section_30_cell_6_4": "`Subscriptions.Update`",
      "section_30_cell_7_0": "`PUT`",
      "section_30_cell_7_1": "`/api/subscriptions/{id}/cancel`",
      "section_30_cell_7_2": "[Cancel subscription]",
      "section_30_cell_7_3": "Required",
      "section_30_cell_7_4": "`Subscriptions.Update`",
      "section_31_title": "TIP",
      "section_31_content": "The downgrade impact analysis API is a powerful sales retention tool. Show customers exactly what they'll lose before they downgrade — creating natural retention moments.",
      "section_32_title": "See Also",
      "section_33_item_0": "[Editions & Plans](../../commercial-docs/19-modules/entitlements)",
      "section_33_item_1": "[Entitlements Overview](../../commercial-docs/19-modules/entitlements)",
